import{_ as t,o as r,c as a,a5 as o}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"Architecture Decision Records (docs/adr/)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/README.md","filePath":"adr/README.md"}'),i={name:"adr/README.md"};function n(s,e,c,d,l,h){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="architecture-decision-records-docs-adr" tabindex="-1">Architecture Decision Records (<code>docs/adr/</code>) <a class="header-anchor" href="#architecture-decision-records-docs-adr" aria-label="Permalink to &quot;Architecture Decision Records (`docs/adr/`)&quot;">​</a></h1><p>&gt; Navigation: <a href="./../">← Knowledge Base Hub</a> · <a href="./../architecture/README.html">System Architecture →</a> · <a href="./../api/README.html">API Contracts →</a> · <a href="./../database/README.html">Database Design →</a></p><p>Architecture Decision Records (ADRs) document the foundational, cross-cutting engineering decisions governing <strong>BrandHub</strong>. Each ADR captures the real constraints faced by the engineering team, the alternatives evaluated and rejected, the exact runtime classes and infrastructure configurations implementing the decision, and the operational trade-offs accepted in production.</p><hr><h2 id="_1-adr-governance-structure" tabindex="-1">1. ADR Governance &amp; Structure <a class="header-anchor" href="#_1-adr-governance-structure" aria-label="Permalink to &quot;1. ADR Governance &amp; Structure&quot;">​</a></h2><p>Every ADR in this directory follows a five-part engineering format:</p><ol><li><strong>Context &amp; Problem Statement</strong>: Functional scale (<code>141</code> FRs across <code>9</code> domains and <code>6</code> canonical roles: <code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code>), team topology, latency/consistency SLAs, and AWS <code>ap-southeast-1</code> cost constraints.</li><li><strong>Evaluated Options</strong>: Concrete architectural alternatives weighed before committing.</li><li><strong>Decision Architecture</strong>: The chosen boundary, protocol, or persistence contract.</li><li><strong>Codebase &amp; Infrastructure Grounding</strong>: Exact Java/Python packages, Spring WebFlux/Boot filters, RabbitMQ exchanges, Docker Compose fragments, and Terraform resources enforcing the decision today.</li><li><strong>Trade-offs &amp; Operational Impact</strong>: Positive outcomes, accepted complexity, and compensating guardrails.</li></ol><hr><h2 id="_2-decision-log" tabindex="-1">2. Decision Log <a class="header-anchor" href="#_2-decision-log" aria-label="Permalink to &quot;2. Decision Log&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">ADR</th><th style="text-align:left;">Title</th><th style="text-align:center;">Status</th><th style="text-align:left;">Core Scope &amp; Cross-References</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="./adr-001-polyrepo.html">ADR-001</a></td><td style="text-align:left;"><strong>Polyrepo Architecture Across 7 Independent Repositories</strong></td><td style="text-align:center;">Accepted</td><td style="text-align:left;">Isolates Java 21 Spring Boot/WebFlux, Python 3.11+ FastAPI, React 19 Vite 8, Expo 58 React Native 0.88, and Terraform/Compose IaC into independent repositories under <code>BrandHubOrganization</code> (<a href="/brandhub-infrastructure/view.html?file=architecture/polyrepo-structure.html">Polyrepo Visualizer</a>, <a href="./../architecture/local-run-architecture.html">Local Run Architecture</a>)</td></tr><tr><td style="text-align:left;"><a href="./adr-002-database-split.html">ADR-002</a></td><td style="text-align:left;"><strong>5-Engine Polyglot Persistence Split</strong></td><td style="text-align:center;">Accepted</td><td style="text-align:left;">Assigns ACID identity, 2-tier RBAC, SePay (VietQR) billing, and AI credit/storage ledgers to <strong>PostgreSQL 17 (<code>97</code> tables)</strong>; nested Tasks/Posts/Chat/Repository/Video to <strong>MongoDB 7.0 (<code>52</code> collections)</strong>; ephemeral auth/rate-limits/trends to <strong>Redis 7.2</strong>; Brand RAG embeddings to <strong>ChromaDB 1.5.9</strong>; and Trend Knowledge Graph to <strong>Neo4j 5.26</strong> (<a href="./../database/README.html">Database Hub</a>, <a href="/brandhub-infrastructure/view.html?file=architecture/db-ownership-diagram.html">DB Ownership Diagram</a>)</td></tr><tr><td style="text-align:left;"><a href="./adr-003-rabbitmq.html">ADR-003</a></td><td style="text-align:left;"><strong>RabbitMQ Direct &amp; TTL-Retry Topology for Social Publishing</strong></td><td style="text-align:center;">Accepted</td><td style="text-align:left;">Decouples <code>brandhub-business-service</code> from external API latency across <strong>Facebook, Instagram, TikTok, and Threads</strong> via <code>publisher.job.exchange</code>, tiered TTL retry queues (<code>1m</code>/<code>5m</code>/<code>15m</code>), <code>publisher.job.dlq</code>, and Redis per-platform locks (<code>processingPostIds:{postId}:{platform}</code>) (<a href="/brandhub-infrastructure/view.html?file=architecture/rabbitmq-publisher-contract.html">RabbitMQ Contract</a>, <a href="./../architecture/service-boundaries.html">Service Boundaries</a>)</td></tr><tr><td style="text-align:left;"><a href="./adr-004-spring-cloud-gateway.html">ADR-004</a></td><td style="text-align:left;"><strong>Spring Cloud Gateway Perimeter, RS256 Auth &amp; Zero-Trust Re-Verification</strong></td><td style="text-align:center;">Accepted</td><td style="text-align:left;">Centralizes ingress at <code>brandhub-api-gateway</code> (<code>InboundSecurityWebFilter</code>, RS256 <code>JWT_PUBLIC_KEY</code> verification, Redis <code>jwt:blacklist:{jti}</code>, Lua sliding-minute rate limiting, STOMP <code>/ws/*</code> routing) while enforcing 2-tier RBAC inside <code>brandhub-business-service</code> (<a href="./../api/rs256-jwt-flow.html">RS256 JWT Flow</a>, <a href="./../api/redis-rate-limiting-filter.html">Rate Limiting</a>)</td></tr></tbody></table><hr><h2 id="_3-architectural-invariants-enforced-across-all-adrs" tabindex="-1">3. Architectural Invariants Enforced Across All ADRs <a class="header-anchor" href="#_3-architectural-invariants-enforced-across-all-adrs" aria-label="Permalink to &quot;3. Architectural Invariants Enforced Across All ADRs&quot;">​</a></h2><ul><li><strong>Single Source of Truth per Entity</strong>: No table or collection is written directly by two microservices (<a href="./../database/redis-cache/database-access-rules.html">Database Access Rules</a>).</li><li><strong>Asymmetric Cryptographic Perimeter</strong>: <code>JWT_PRIVATE_KEY</code>, <code>AES_SECRET_KEY</code>, and <code>REPOSITORY_ENCRYPTION_KEY_V1</code> never reside on the public edge gateway.</li><li><strong>Strict Scope Alignment</strong>: Only the <strong>4 supported social platforms</strong> (Facebook, Instagram, TikTok, Threads) and <strong>SePay (VietQR)</strong> upgrade-only / credit-pack billing flows are implemented across service contracts.</li></ul>',13)])])}const p=t(i,[["render",n]]);export{u as __pageData,p as default};
